impl Solution {
    pub fn minimum_deletions(nums: Vec<i32>) -> i32 {
        let min_val = *nums.iter().min().unwrap();
        let max_val = *nums.iter().max().unwrap();

        let min_idx = nums.iter().position(|&x| x == min_val).unwrap();
        let max_idx = nums.iter().position(|&x| x == max_val).unwrap();

        let left = if min_idx <= max_idx {
            max_idx + 1
        } else {
            min_idx + 1
        };

        let right = if min_idx <= max_idx {
            nums.len() - min_idx
        } else {
            nums.len() - max_idx
        };

        let both = if min_idx <= max_idx {
            min_idx + 1 + nums.len() - max_idx
        } else {
            max_idx + 1 + nums.len() - min_idx
        };

        if left <= right && left <= both {
            left as i32
        } else if right <= both {
            right as i32
        } else {
            both as i32
        }
    }
}

